CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE staff_role AS ENUM ('ADMIN','DOOR_STAFF');
CREATE TYPE event_status AS ENUM ('DRAFT','UPCOMING','SOLD_OUT','CANCELLED','POSTPONED','COMPLETED');
CREATE TYPE order_status AS ENUM ('AWAITING_PAYMENT_PROOF','PAYMENT_PROOF_SUBMITTED','UNDER_ORGANISER_REVIEW','PAYMENT_REJECTED','CONFIRMED','EXPIRED','CANCELLED','REFUNDED');
CREATE TYPE proof_status AS ENUM ('SUBMITTED','SUPERSEDED','APPROVED','REJECTED');
CREATE TYPE review_decision AS ENUM ('APPROVED','REJECTED');
CREATE TABLE staff_user(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,role staff_role NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE category(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,name text NOT NULL);
CREATE TABLE event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL,summary text NOT NULL,description text NOT NULL,status event_status NOT NULL DEFAULT 'DRAFT',category_id uuid NOT NULL REFERENCES category(id),starts_at timestamptz NOT NULL,doors_at timestamptz,venue text NOT NULL,age_guidance text,language text,accessibility text,image_key text,featured boolean NOT NULL DEFAULT false,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_tier(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES event(id) ON DELETE CASCADE,name text NOT NULL,price_minor integer NOT NULL CHECK(price_minor>=0),currency char(3) NOT NULL DEFAULT 'PKR',capacity integer NOT NULL CHECK(capacity>=0),sold integer NOT NULL DEFAULT 0 CHECK(sold>=0 AND sold<=capacity),sales_start timestamptz,sales_end timestamptz,per_order_limit integer NOT NULL DEFAULT 4 CHECK(per_order_limit>0),UNIQUE(event_id,name));
CREATE TABLE customer_order(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_reference text UNIQUE NOT NULL,access_token_hash text NOT NULL,status order_status NOT NULL DEFAULT 'AWAITING_PAYMENT_PROOF',event_id uuid NOT NULL REFERENCES event(id),full_name text NOT NULL,email text NOT NULL,phone text NOT NULL,currency char(3) NOT NULL DEFAULT 'PKR',subtotal_minor integer NOT NULL CHECK(subtotal_minor>=0),fee_minor integer NOT NULL DEFAULT 0 CHECK(fee_minor>=0),total_minor integer NOT NULL CHECK(total_minor>=0),hold_expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,cancelled_at timestamptz,refunded_at timestamptz);
CREATE TABLE order_item(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES customer_order(id) ON DELETE CASCADE,tier_id uuid NOT NULL REFERENCES ticket_tier(id),quantity integer NOT NULL CHECK(quantity>0),unit_price_minor integer NOT NULL CHECK(unit_price_minor>=0),line_total_minor integer NOT NULL CHECK(line_total_minor>=0));
CREATE TABLE inventory_hold(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES customer_order(id) ON DELETE CASCADE,tier_id uuid NOT NULL REFERENCES ticket_tier(id),quantity integer NOT NULL CHECK(quantity>0),expires_at timestamptz NOT NULL,converted_at timestamptz,released_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_proof(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES customer_order(id) ON DELETE CASCADE,storage_key text UNIQUE NOT NULL,detected_mime text NOT NULL CHECK(detected_mime IN ('image/jpeg','image/png','image/webp')),size_bytes integer NOT NULL CHECK(size_bytes>0),width_px integer,height_px integer,metadata_stripped boolean NOT NULL DEFAULT false,version integer NOT NULL CHECK(version>0),status proof_status NOT NULL DEFAULT 'SUBMITTED',uploaded_at timestamptz NOT NULL DEFAULT now(),delete_after timestamptz,transfer_at timestamptz,sender_name text,transaction_reference text,note text,UNIQUE(order_id,version));
CREATE TABLE payment_review(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES customer_order(id),proof_id uuid NOT NULL REFERENCES payment_proof(id),reviewer_id uuid NOT NULL REFERENCES staff_user(id),decision review_decision NOT NULL,internal_note text NOT NULL,customer_reason text,idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_id text UNIQUE NOT NULL,order_id uuid NOT NULL REFERENCES customer_order(id),tier_id uuid NOT NULL REFERENCES ticket_tier(id),signed_payload_hash text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'VALID',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE check_in(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid UNIQUE NOT NULL REFERENCES ticket(id),staff_id uuid NOT NULL REFERENCES staff_user(id),checked_in_at timestamptz NOT NULL DEFAULT now(),undone_at timestamptz,undo_reason text);
CREATE TABLE refund_record(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES customer_order(id),amount_minor integer NOT NULL CHECK(amount_minor>=0),currency char(3) NOT NULL DEFAULT 'PKR',method text NOT NULL,reference text,reason text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES staff_user(id),action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organiser_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),payment_method text NOT NULL,provider_name text NOT NULL,account_title text NOT NULL,account_identifier text NOT NULL,instructions text NOT NULL,hold_minutes integer NOT NULL CHECK(hold_minutes BETWEEN 5 AND 1440),rejection_resubmit_minutes integer NOT NULL CHECK(rejection_resubmit_minutes BETWEEN 5 AND 1440),support_contact text NOT NULL,receipt_retention_days integer NOT NULL CHECK(receipt_retention_days BETWEEN 1 AND 365),placeholder_active boolean NOT NULL DEFAULT true,updated_by uuid REFERENCES staff_user(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_delivery(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES customer_order(id),template_key text NOT NULL,recipient text NOT NULL,status text NOT NULL CHECK(status IN ('PREVIEW','QUEUED','SENT','FAILED')),provider_message_id text,error text,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX event_programme_idx ON event(status,starts_at);CREATE INDEX order_status_expiry_idx ON customer_order(status,hold_expires_at);CREATE INDEX order_email_idx ON customer_order(lower(email));CREATE INDEX order_phone_idx ON customer_order(phone);CREATE INDEX hold_tier_expiry_idx ON inventory_hold(tier_id,expires_at);CREATE INDEX proof_review_idx ON payment_proof(status,uploaded_at);CREATE INDEX proof_transaction_idx ON payment_proof(transaction_reference);CREATE INDEX audit_entity_idx ON audit_log(entity_type,entity_id,created_at DESC);
